def vehicle_shadow_zone_violation(
    candidate_mask,
    vehicle_oracle_region,
) -> float:
    """
    Frozen Block6.6 definition:

        |O_vehicle \ D| / |O_vehicle|

    No vehicle cells:
        NA -> NaN
    """

    candidate = _bool_array(
        candidate_mask,
        name="candidate_mask",
    )

    vehicle = _bool_array(
        vehicle_oracle_region,
        name="vehicle_oracle_region",
    )

    _same_shape(
        candidate,
        vehicle,
    )

    denominator = int(
        np.count_nonzero(
            vehicle
        )
    )

    if denominator == 0:
        return float(
            "nan"
        )

    missed = int(
        np.count_nonzero(
            vehicle
            &
            ~candidate
        )
    )

    return float(
        missed
        /
        denominator
    )

def glare_risk_exposure(
    intensity,
    vehicle_surrogate_reference_region,
) -> float:
    """
    Mean final normalized intensity over the constructed
    vehicle front-upper/rear-upper surrogate reference cells.

    Lower is better.

    Empty evaluator support is reported as NaN.
    """

    light = _intensity_array(
        intensity,
        name="intensity",
    )

    region = _bool_array(
        vehicle_surrogate_reference_region,
        name=(
            "vehicle_surrogate_reference_region"
        ),
    )

    _same_shape(
        light,
        region,
    )

    if not np.any(
        region
    ):
        return float(
            "nan"
        )

    return float(
        np.mean(
            light[
                region
            ]
        )
    )

