def road_illumination_retention(
    intensity,
    road_roi,
) -> float:
    """
    Frozen Block6.6 definition:

        mean(I_final over frozen road ROI)

    Higher is better.
    """

    light = _intensity_array(
        intensity,
        name="intensity",
    )

    road = _bool_array(
        road_roi,
        name="road_roi",
    )

    _same_shape(
        light,
        road,
    )

    if not np.any(
        road
    ):
        raise ValueError(
            "road_roi must contain at least one cell"
        )

    return float(
        np.mean(
            light[
                road
            ]
        )
    )
